mockup.css:
.mock-section-index-table { background: #faf8f2; color: #171510; font-family: var(--f-sans);
  padding: 5cqw 6cqw; display: flex; flex-direction: column; gap: 2.6cqw; }
.mock-section-index-table .head { display: flex; justify-content: space-between; align-items: baseline; gap: 2cqw; }
.mock-section-index-table h4 { margin: 0; font-family: var(--f-serif); font-size: 3.4cqw; }
.mock-section-index-table .head span { font-family: var(--f-mono); font-size: 1.15cqw;
  letter-spacing: .16em; text-transform: uppercase; opacity: .45; }
.mock-section-index-table .r { display: grid; grid-template-columns: 1fr 32% 9cqw; gap: 2.4cqw; align-items: baseline;
  border-top: 1px solid rgba(23,21,16,.16); padding: 1.5cqw 0; }
.mock-section-index-table .r b { font-weight: 600; font-size: 1.9cqw; }
.mock-section-index-table .r span { font-size: 1.35cqw; opacity: .58; }
.mock-section-index-table .r em { font-style: normal; font-family: var(--f-mono); font-size: 1.45cqw; text-align: end; }
